<?php
/** Shared community/creator/shop domain. Uses existing native member and transactional document stores. */
declare(strict_types=1);
require_once __DIR__.'/subscription-core.php';require_once __DIR__.'/ecosystem-features.php';
const NECO_CATEGORIES=['lounge'=>['chat','music','story','diary','event','notice'],'lab'=>['work','feedback','collaboration','class','challenge','growth']];
function eco_actor():array{global $member,$is_admin;$a=['id'=>(string)($member['mb_id']??''),'level'=>(int)($member['mb_level']??1),'name'=>(string)($member['mb_nick']??$member['mb_name']??'회원'),'admin'=>($is_admin??'')==='super'];$a['capabilities']=eco_capabilities($a);return $a;}
function eco_text(mixed $v,int $max,bool $required=false):string{if(!is_string($v)||!mb_check_encoding($v,'UTF-8')||str_contains($v,"\0")||mb_strlen($v)>$max||($required&&trim($v)===''))throw new InvalidArgumentException('invalid_text');return trim($v);}
function eco_id(string $id):string{if(!preg_match('/^[a-f0-9]{32}$/D',$id))throw new InvalidArgumentException('invalid_id');return $id;}
function eco_require(array $a,int $level=2):void{if($a['id']===''||(!$a['admin']&&$a['level']<$level))throw new DomainException('membership_required');}
function eco_creator(array $a):void{eco_require($a);if(!$a['admin']&&!in_array($a['level'],[5,6],true))throw new DomainException('creator_required');}
function eco_readable(array $d,array $a):bool{return empty($d['deleted'])&&($a['admin']||($a['id']!==''&&($d['owner']??null)===$a['id'])||(($d['visibility']??'public')==='public'&&eco_perks_allowed($d,$a))||(($d['visibility']??'')==='members'&&$a['id']!==''&&eco_perks_allowed($d,$a)));}
function eco_record(string $id,array $a,bool $lock=false):array{$r=ns_doc('ecosystem:post:'.eco_id($id),$lock);if(!$r||$r['kind']!=='ecosystem_post'||!eco_readable($r['data'],$a))throw new DomainException('not_found');return $r;}
function eco_owner(array $r,array $a):void{eco_require($a);if(!$a['admin']&&$r['data']['owner']!==$a['id'])throw new DomainException('owner_required');}
function eco_note(string $owner,string $actor,string $post,string $text,string $event):void{if($owner===$actor||$owner==='')return;$key='ecosystem:notice:'.hash('sha256',$owner.'|'.$event);if(ns_doc($key))return;ns_put($key,'ecosystem_notice',['owner'=>$owner,'post'=>$post,'text'=>$text,'at'=>time(),'read'=>false],0,$actor);}
function eco_relation(string $id,string $kind,string $owner):string{return 'ecosystem:relation:'.hash('sha256',$id.'|'.$kind.'|'.$owner);}
function eco_public(array $r,array $a):array{$d=$r['data'];$d['revision']=$r['revision'];$d['mine']=$a['id']!==''&&$d['owner']===$a['id'];$channelId=hash('sha256',$d['owner']);$d['channelId']=ns_doc('creator-channel:'.$channelId)?$channelId:'';unset($d['owner']);$d['liked']=$a['id']!==''&&!empty(ns_doc(eco_relation($d['id'],'like',$a['id']))['data']['active']);$d['bookmarked']=$a['id']!==''&&!empty(ns_doc(eco_relation($d['id'],'bookmark',$a['id']))['data']['active']);return $d;}
function eco_acl_sql(array $a):string{$own=$a['id']!==''?" OR JSON_UNQUOTE(JSON_EXTRACT(payload,'$.owner'))=".ns_e($a['id']):'';return "COALESCE(JSON_EXTRACT(payload,'$.deleted'),false)=false".($a['admin']?'':" AND (JSON_UNQUOTE(JSON_EXTRACT(payload,'$.visibility'))='public'".($a['id']!==''?" OR JSON_UNQUOTE(JSON_EXTRACT(payload,'$.visibility'))='members'":'').$own.')').($a['admin']||eco_vip($a)?'':" AND (COALESCE(JSON_EXTRACT(payload,'$.vipOnly'),false)=false OR (CAST(JSON_EXTRACT(payload,'$.releaseAt') AS UNSIGNED)>0 AND CAST(JSON_EXTRACT(payload,'$.releaseAt') AS UNSIGNED)<=".time().")".$own.")");}
function eco_list(array $a,array $q):array{$space=in_array($q['space']??'', ['lounge','lab'],true)?$q['space']:'lounge';$page=max(1,min(1000,(int)($q['page']??1)));$where="kind='ecosystem_post' AND ".eco_acl_sql($a)." AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.space'))=".ns_e($space);
 if(!empty($q['category']))$where.=" AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.category'))=".ns_e(eco_text($q['category'],30));if(!empty($q['q'])){$s=eco_text($q['q'],80);$where.=" AND LOCATE(".ns_e(mb_strtolower($s)).",LOWER(CONCAT(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.title')),' ',JSON_UNQUOTE(JSON_EXTRACT(payload,'$.body')))))>0";}
 if(($q['mine']??'')==='1'){$where.=" AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.owner'))=".ns_e($a['id']?:'__guest__');}
 if(($q['saved']??'')==='1'){$where.=" AND doc_key IN (SELECT CONCAT('ecosystem:post:',JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.post'))) FROM noa_documents r WHERE r.kind='ecosystem_relation' AND JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.owner'))=".ns_e($a['id']?:'__guest__')." AND JSON_UNQUOTE(JSON_EXTRACT(r.payload,'$.type'))='bookmark' AND JSON_EXTRACT(r.payload,'$.active')=true)";}
 $order=($q['sort']??'')==='popular'?"CAST(JSON_EXTRACT(payload,'$.likes') AS UNSIGNED) DESC,updated_at DESC":"updated_at DESC";$n=(int)ns_one('SELECT COUNT(*) n FROM noa_documents WHERE '.$where)['n'];$rows=[];$res=ns_q('SELECT payload,revision FROM noa_documents WHERE '.$where.' ORDER BY '.$order.' LIMIT 12 OFFSET '.(($page-1)*12));while($r=sql_fetch_array($res)){$v=eco_public(['data'=>json_decode($r['payload'],true,64,JSON_THROW_ON_ERROR),'revision'=>(int)$r['revision']],$a);$v['body']=mb_substr($v['body'],0,160);$rows[]=$v;}return ['items'=>$rows,'total'=>$n,'page'=>$page,'pages'=>max(1,(int)ceil($n/12))];}
function eco_detail(string $id,array $a):array{$r=eco_record($id,$a);$d=eco_public($r,$a);$comments=[];$q=ns_q("SELECT payload,revision FROM noa_documents WHERE kind='ecosystem_comment' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.post'))=".ns_e($id)." ORDER BY updated_at ASC LIMIT 200");while($x=sql_fetch_array($q)){$v=json_decode($x['payload'],true,64,JSON_THROW_ON_ERROR);$v['mine']=$v['owner']===$a['id'];if(!$a['admin']&&!$d['mine']&&!$v['mine']&&($v['visibility']??'public')!=='public'&&!(($v['visibility']??'')==='members'&&$a['id']!==''))continue;unset($v['owner']);$v['revision']=(int)$x['revision'];if(!empty($v['deleted'])){$v['body']='삭제된 댓글입니다.';$v['name']='';}$comments[]=$v;}
 $versions=[];$q=ns_q("SELECT payload FROM noa_documents WHERE kind='ecosystem_version' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.post'))=".ns_e($id)." ORDER BY updated_at DESC LIMIT 50");while($x=sql_fetch_array($q)){$v=json_decode($x['payload'],true,64,JSON_THROW_ON_ERROR);if(!$a['admin']&&!$d['mine']&&!eco_perks_allowed($v,$a))continue;if(!$a['admin']&&!$d['mine']&&($v['visibility']??'private')!=='public'&&!(($v['visibility']??'')==='members'&&$a['id']!==''))continue;unset($v['owner']);$versions[]=$v;}
 $applications=[];if($d['mine']||$a['admin']){$q=ns_q("SELECT payload FROM noa_documents WHERE kind='ecosystem_application' AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.post'))=".ns_e($id)." ORDER BY updated_at DESC LIMIT 100");while($x=sql_fetch_array($q)){$v=json_decode($x['payload'],true,64,JSON_THROW_ON_ERROR);unset($v['owner']);$applications[]=$v;}}
 $entries=[];if($d['category']==='challenge'){$eq=ns_q("SELECT payload,revision FROM noa_documents WHERE kind='ecosystem_post' AND ".eco_acl_sql($a)." AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.challenge'))=".ns_e($id)." ORDER BY updated_at DESC LIMIT 50");while($er=sql_fetch_array($eq)){$ev=json_decode($er['payload'],true);$entries[]=['id'=>$ev['id'],'title'=>$ev['title'],'name'=>$ev['name']];}}$vote=$a['id']!==''?(ns_doc(eco_relation($id,'vote',$a['id']))['data']['option']??null):null;return ['post'=>$d,'comments'=>$comments,'versions'=>$versions,'applications'=>$applications,'vote'=>$vote,'entries'=>$entries];}
function eco_video(string $url):string{if($url==='')return '';if(!preg_match('~^https://(?:www\.)?(?:youtube\.com/(?:watch\?v=|shorts/)|youtu\.be/)([A-Za-z0-9_-]{11})(?:[?&].*)?$~D',$url,$m))throw new InvalidArgumentException('youtube_url_required');return 'https://www.youtube.com/watch?v='.$m[1];}
function eco_music(string $key,array $a):?array{if($key==='')return null;eco_require($a);$original=ns_doc($key);if(($original['data']['visibility']??'public')!=='public')throw new DomainException('public_music_required');require_once __DIR__.'/storage.php';require_once __DIR__.'/engagement-targets.php';$t=ne_target(noa_bridge_pdo(),'music',$key);return ['key'=>$key,'title'=>$t['title']];}
function eco_save(array $a,array $b):array{eco_require($a,3);$space=$b['space']??'';if(!isset(NECO_CATEGORIES[$space])||!in_array($b['category']??'',NECO_CATEGORIES[$space],true))throw new InvalidArgumentException('invalid_category');if($space==='lab')eco_creator($a);if(in_array($b['category'],['notice','diary'],true)&&!eco_can($a,'community'))throw new DomainException('administrator_required');
 $id=eco_id((string)($b['id']??''));$title=eco_text($b['title']??'',120,true);$body=eco_text($b['body']??'',20000,true);$visibility=$b['visibility']??'public';if(!in_array($visibility,['public','members','private'],true))throw new InvalidArgumentException('invalid_visibility');$youtube=eco_video(eco_text($b['youtube']??'',500));$music=eco_music(eco_text($b['musicKey']??'',220),$a);
 $vipOnly=($b['vipOnly']??false)===true;$releaseAt=$b['releaseAt']??0;if(!is_int($releaseAt)||$releaseAt<0)throw new InvalidArgumentException('invalid_release');if($vipOnly&&(!eco_can($a,'community')||$space!=='lounge'||!in_array($b['category'],['diary','event','notice'],true)))throw new DomainException('vip_publishing_required');$playlist=eco_reference_url(eco_text($b['playlistUrl']??'',500));
 $images=$b['images']??[];if(!is_array($images)||count($images)>4)throw new InvalidArgumentException('invalid_images');foreach($images as $image){$asset=ns_doc('ecosystem:asset:'.eco_id((string)$image));if(!$asset||$asset['data']['owner']!==$a['id'])throw new DomainException('own_image_required');}
 $challenge=(string)($b['challenge']??'');if($challenge!==''){$challenge=eco_id($challenge);$cr=eco_record($challenge,$a);if($space!=='lab'||$cr['data']['category']!=='challenge'||in_array($cr['data']['stage'],['closed','complete'],true))throw new DomainException('challenge_closed');}
 $options=$b['options']??[];if(!is_array($options)||count($options)>6||(count($options)===1))throw new InvalidArgumentException('invalid_poll');$options=array_map(fn($x)=>eco_text($x,100,true),$options);if(count(array_unique($options))!==count($options))throw new InvalidArgumentException('invalid_poll');
 $fields=[];foreach(['roles','schedule','compensation','rights','changes','feedbackFocus']as $f)$fields[$f]=eco_text($b[$f]??'',2000);if($b['category']==='collaboration')foreach(['roles','schedule','compensation','rights']as $f)if($fields[$f]==='')throw new InvalidArgumentException('collaboration_terms_required');if($space==='lab'&&($b['rightsConfirmed']??false)!==true)throw new DomainException('rights_confirmation_required');
 return ns_atomic('ecosystem:post:'.$id,false,function()use($a,$b,$space,$id,$title,$body,$visibility,$youtube,$music,$images,$options,$fields,$challenge,$vipOnly,$releaseAt,$playlist){$key='ecosystem:post:'.$id;$old=ns_doc($key,true);if($old){eco_owner($old,$a);if($old['data']['space']!==$space||!empty($old['data']['deleted']))throw new DomainException('not_found');}if(!is_int($b['revision']??null)||$b['revision']!==($old['revision']??0))throw new DomainException('revision_conflict');
 if($old&&($old['data']['options']??[])!==$options&&array_sum($old['data']['votes']??[])>0)throw new DomainException('poll_has_votes');
 $d=array_replace($old['data']??[],['id'=>$id,'owner'=>$old['data']['owner']??$a['id'],'name'=>$old['data']['name']??$a['name'],'space'=>$space,'category'=>$b['category'],'title'=>$title,'body'=>$body,'visibility'=>$visibility,'vipOnly'=>$vipOnly,'releaseAt'=>$releaseAt,'playlist'=>$playlist,'youtube'=>$youtube,'music'=>$music,'images'=>$images,'challenge'=>$challenge,'options'=>$options,'votes'=>$old['data']['votes']??array_fill(0,count($options),0),'likes'=>$old['data']['likes']??0,'comments'=>$old['data']['comments']??0,'at'=>$old['data']['at']??time(),'updated'=>time(),'stage'=>$old['data']['stage']??'draft','downloadAllowed'=>($b['downloadAllowed']??false)===true,'remixAllowed'=>($b['remixAllowed']??false)===true],$fields);
 $v=ns_put($key,'ecosystem_post',$d,$old['revision']??0,$a['id']);foreach($images as $image){$k='ecosystem:asset:'.$image;$r=ns_doc($k,true);if(!empty($r['data']['post'])&&$r['data']['post']!==$id)throw new DomainException('image_already_attached');$r['data']['post']=$id;ns_put($k,'ecosystem_asset',$r['data'],$r['revision'],$a['id']);}
 if($space==='lab'){ns_put('ecosystem:version:'.$id.':'.$v,'ecosystem_version',['post'=>$id,'version'=>$v,'vipOnly'=>$vipOnly,'releaseAt'=>$releaseAt,'visibility'=>$visibility,'title'=>$title,'body'=>$body,'changes'=>$fields['changes'],'music'=>$music,'youtube'=>$youtube,'at'=>time()],0,$a['id']);}
 return ['id'=>$id,'revision'=>$v];});}
function eco_mutate(array $a,string $action,array $b):array{eco_require($a,3);$id=eco_id((string)($b['id']??''));return ns_atomic('ecosystem:post:'.$id,false,function()use($a,$action,$b,$id){$r=eco_record($id,$a,true);$d=$r['data'];$key='ecosystem:post:'.$id;
 if($action==='delete'||$action==='stage'){eco_owner($r,$a);if(($b['revision']??null)!==$r['revision'])throw new DomainException('revision_conflict');if($action==='delete')$d['deleted']=true;else{if(!in_array($b['stage']??'', ['draft','feedback','revision','complete','closed'],true))throw new InvalidArgumentException('invalid_stage');$d['stage']=$b['stage'];}$v=ns_put($key,'ecosystem_post',$d,$r['revision'],$a['id']);return ['revision'=>$v];}
 if(in_array($action,['like','bookmark','vote'],true)){$k=eco_relation($id,$action,$a['id']);$old=ns_doc($k,true);$v=['owner'=>$a['id'],'post'=>$id,'type'=>$action,'active'=>true];if($action==='vote'){$i=$b['option']??null;if(!is_int($i)||!isset($d['options'][$i]))throw new InvalidArgumentException('invalid_option');if($old)throw new DomainException('already_voted');$v['option']=$i;$d['votes'][$i]=($d['votes'][$i]??0)+1;}else{if(!is_bool($b['active']??null))throw new InvalidArgumentException('invalid_active');$v['active']=$b['active'];if($action==='like')$d['likes']=max(0,$d['likes']+(int)$v['active']-(int)($old['data']['active']??false));}ns_put($k,'ecosystem_relation',$v,$old['revision']??0,$a['id']);if($action!=='bookmark')ns_put($key,'ecosystem_post',$d,$r['revision'],$a['id']);return ['active'=>$v['active']];}
 if($action==='comment'){$cid=eco_id((string)($b['commentId']??''));$k='ecosystem:comment:'.$cid;$old=ns_doc($k,true);$text=eco_text($b['body']??'',3000,true);$parent=(string)($b['parent']??'');if($parent!==''){$p=ns_doc('ecosystem:comment:'.eco_id($parent));if(!$p||$p['data']['post']!==$id)throw new DomainException('invalid_parent');}
 if($old){if($old['data']['post']!==$id||($old['data']['owner']!==$a['id']&&!$a['admin']))throw new DomainException('owner_required');if(($b['revision']??null)!==$old['revision'])throw new DomainException('revision_conflict');}elseif(($b['revision']??0)!==0)throw new DomainException('revision_conflict');
 $c=['id'=>$cid,'post'=>$id,'owner'=>$old['data']['owner']??$a['id'],'name'=>$old['data']['name']??$a['name'],'visibility'=>$old['data']['visibility']??$d['visibility'],'body'=>$text,'parent'=>$old['data']['parent']??$parent,'at'=>$old['data']['at']??time(),'topic'=>eco_text($b['topic']??'일반',60),'resolved'=>$old['data']['resolved']??false,'resolution'=>$old['data']['resolution']??null,'version'=>$old['data']['version']??($d['space']==='lab'?eco_latest_version($id):0)];ns_put($k,'ecosystem_comment',$c,$old['revision']??0,$a['id']);if(!$old){$d['comments']++;ns_put($key,'ecosystem_post',$d,$r['revision'],$a['id']);eco_note($d['owner'],$a['id'],$id,'새 댓글·피드백이 도착했습니다.',$cid);if(isset($p))eco_note($p['data']['owner'],$a['id'],$id,'내 댓글에 답글이 도착했습니다.',$cid.'reply');}return ['id'=>$cid];}
 if(in_array($action,['comment-delete','resolve'],true)){$k='ecosystem:comment:'.eco_id((string)($b['commentId']??''));$c=ns_doc($k,true);if(!$c||$c['data']['post']!==$id)throw new DomainException('not_found');if($action==='resolve')eco_owner($r,$a);elseif(!$a['admin']&&$c['data']['owner']!==$a['id'])throw new DomainException('owner_required');$c['data'][$action==='resolve'?'resolved':'deleted']=true;ns_put($k,'ecosystem_comment',$c['data'],$c['revision'],$a['id']);return ['ok'=>true];}
 if($action==='report'){$reason=eco_text($b['reason']??'',1500,true);$k='ecosystem:report:'.hash('sha256',$id.'|'.$a['id']);$old=ns_doc($k,true);ns_put($k,'ecosystem_report',['post'=>$id,'owner'=>$a['id'],'reason'=>$reason,'status'=>'open','at'=>time()],$old['revision']??0,$a['id']);return ['ok'=>true];}
 if($action==='apply'){eco_creator($a);if($d['category']!=='collaboration'||$d['stage']==='closed')throw new DomainException('recruitment_closed');if($d['owner']===$a['id'])throw new DomainException('own_application');if(($b['consent']??false)!==true)throw new DomainException('terms_confirmation_required');$k='ecosystem:application:'.hash('sha256',$id.'|'.$a['id']);$old=ns_doc($k,true);if($old)throw new DomainException('already_applied');ns_put($k,'ecosystem_application',['id'=>substr($k,strrpos($k,':')+1),'owner'=>$a['id'],'name'=>$a['name'],'channelId'=>hash('sha256',$a['id']),'post'=>$id,'message'=>eco_text($b['message']??'',3000,true),'terms'=>['roles'=>$d['roles'],'schedule'=>$d['schedule'],'compensation'=>$d['compensation'],'rights'=>$d['rights']],'status'=>'requested','at'=>time()],0,$a['id']);eco_note($d['owner'],$a['id'],$id,'협업 참여 신청이 도착했습니다.',$k);return ['ok'=>true];}
 if($action==='application-review'){eco_owner($r,$a);$app=(string)($b['application']??'');if(!preg_match('/^[a-f0-9]{64}$/D',$app)||!in_array($b['status']??'', ['accepted','declined'],true))throw new InvalidArgumentException('invalid_application');$k='ecosystem:application:'.$app;$x=ns_doc($k,true);if(!$x||$x['data']['post']!==$id)throw new DomainException('not_found');$x['data']['status']=$b['status'];ns_put($k,'ecosystem_application',$x['data'],$x['revision'],$a['id']);eco_note($x['data']['owner'],$a['id'],$id,'협업 신청 결과를 확인해 주세요.',$k.$b['status']);return ['ok'=>true];}
 throw new InvalidArgumentException('unknown_action');});}
function eco_activity(array $a):array{eco_require($a);$out=['notices'=>[],'applications'=>[]];foreach(['notices'=>'ecosystem_notice','applications'=>'ecosystem_application']as $field=>$kind){$q=ns_q('SELECT doc_key,payload FROM noa_documents WHERE kind='.ns_e($kind)." AND JSON_UNQUOTE(JSON_EXTRACT(payload,'$.owner'))=".ns_e($a['id']).' ORDER BY updated_at DESC LIMIT 50');while($r=sql_fetch_array($q)){$d=json_decode($r['payload'],true,64,JSON_THROW_ON_ERROR);try{eco_record($d['post'],$a);}catch(DomainException){continue;}$d['key']=$r['doc_key'];unset($d['owner']);$out[$field][]=$d;}}return $out;}
